+import { formatUnitsFixed } from '@/onchain-money'
+import { USDC_DECIMALS } from '@/onchain-facts'
+
+/** USDC with all 6 decimals, e.g. "1,250.500000". */
+export function fmtUsdc(raw: bigint): string {
+  const [whole, frac] = formatUnitsFixed(raw, USDC_DECIMALS, USDC_DECIMALS).split('.')
+  return `${BigInt(whole).toLocaleString('en-US')}.${frac}`
+}
+
+/** Split into whole part and 6-digit fraction so the UI can dim the decimals. */
+export function splitUsdc(raw: bigint): { whole: string; frac: string } {
+  const [whole, frac] = fmtUsdc(raw).split('.')
+  return { whole, frac }
+}
+
+export function shortAddr(addr: string): string {
+  return `${addr.slice(0, 6)}…${addr.slice(-4)}`
+}
+
+export function shortHash(hash: string): string {
+  return `${hash.slice(0, 10)}…${hash.slice(-6)}`
+}
+
+/** "2d 3h", "4h 12m", "3m 05s", "42s". */
+export function fmtDuration(totalSeconds: number): string {
+  const s = Math.max(0, Math.floor(totalSeconds))
+  const d = Math.floor(s / 86400)
+  const h = Math.floor((s % 86400) / 3600)
+  const m = Math.floor((s % 3600) / 60)
+  const sec = s % 60
+  if (d > 0) return `${d}d ${h}h`
+  if (h > 0) return `${h}h ${m.toString().padStart(2, '0')}m`
+  if (m > 0) return `${m}m ${sec.toString().padStart(2, '0')}s`
+  return `${sec}s`
+}
+
+export function fmtDateTime(unixSeconds: number | bigint): string {
+  return new Date(Number(unixSeconds) * 1000).toLocaleString(undefined, {
+    month: 'short',
+    day: 'numeric',
+    hour: '2-digit',
+    minute: '2-digit',
+  })
+}
+
+/** Value for <input type="datetime-local"> in local time. */
+export function toLocalInputValue(unixSeconds: number): string {
+  const d = new Date(unixSeconds * 1000)
+  const pad = (n: number) => n.toString().padStart(2, '0')
+  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
+}
+
+export function fromLocalInputValue(value: string): number | null {
+  if (!value) return null
+  const ms = new Date(value).getTime()
+  return Number.isFinite(ms) ? Math.floor(ms / 1000) : null
+}
+
+export function utf8Length(value: string): number {
+  return new TextEncoder().encode(value).length
+}

+import { decodeEventLog, getAbiItem, pad, toEventSelector, toHex, type Address, type Hex, type PublicClient } from 'viem'
+import { onTheLineAbi } from '@/abi/onTheLine'
+
+export type TxKind = 'created' | 'kept' | 'forfeited' | 'settled'
+
+export interface PledgeTx {
+  kind: TxKind
+  hash: Hex
+  blockNumber?: bigint
+}
+
+/** Window size per eth_getLogs call. Measured on Arc: 5,000 blocks succeeded, 10,000 was rejected. */
+const WINDOW = 4000n
+const CONCURRENCY = 6
+
+const TOPICS = (['PledgeCreated', 'PledgeKept', 'PledgeForfeited'] as const).map((name) =>
+  toEventSelector(getAbiItem({ abi: onTheLineAbi, name })),
+)
+
+export interface ScanProgress {
+  head: bigint
+  start: bigint
+  /** Lowest block scanned so far. */
+  scannedFrom: bigint
+}
+
+interface RawLog {
+  topics: Hex[]
+  data: Hex
+  transactionHash: Hex
+  blockNumber: Hex
+}
+
+function kindOf(raw: RawLog): TxKind | null {
+  try {
+    const ev = decodeEventLog({ abi: onTheLineAbi, data: raw.data, topics: raw.topics as [Hex, ...Hex[]] })
+    if (ev.eventName === 'PledgeCreated') return 'created'
+    if (ev.eventName === 'PledgeKept') return 'kept'
+    if (ev.eventName === 'PledgeForfeited') return ev.args.expired ? 'settled' : 'forfeited'
+  } catch {
+    return null
+  }
+  return null
+}
+
+/**
+ * Finds every event for one pledge id. Scans backwards from the chain head toward the
+ * deployment block (never from block 0) and stops once the PledgeCreated event is found,
+ * since it is always the first event for an id.
+ */
+export async function scanPledgeTxs(
+  client: PublicClient,
+  address: Address,
+  id: bigint,
+  startBlock: bigint,
+  onProgress: (p: ScanProgress) => void,
+): Promise<PledgeTx[]> {
+  const head = await client.getBlockNumber()
+  const idTopic = pad(toHex(id), { size: 32 })
+  const found: PledgeTx[] = []
+  let to = head
+  let createdSeen = false
+
+  while (to >= startBlock && !createdSeen) {
+    const windows: Array<[bigint, bigint]> = []
+    for (let i = 0; i < CONCURRENCY && to >= startBlock; i++) {
+      const from = to - WINDOW + 1n > startBlock ? to - WINDOW + 1n : startBlock
+      windows.push([from, to])
+      to = from - 1n
+    }
+    const results = await Promise.all(
+      windows.map(([from, end]) =>
+        client.request({
+          method: 'eth_getLogs',
+          params: [{ address, fromBlock: toHex(from), toBlock: toHex(end), topics: [TOPICS, idTopic] }],
+        }) as Promise<RawLog[]>,
+      ),
+    )
+    for (const logs of results) {
+      for (const log of logs) {
+        const kind = kindOf(log)
+        if (!kind) continue
+        if (kind === 'created') createdSeen = true
+        found.push({ kind, hash: log.transactionHash, blockNumber: BigInt(log.blockNumber) })
+      }
+    }
+    const lowest = windows[windows.length - 1][0]
+    onProgress({ head, start: startBlock, scannedFrom: lowest })
+  }
+  return found
+}
